    if (tb[DW_TOPOLOGY_HISTORY_END]) end_ms = (int64_t)blobmsg_get_u64(tb[DW_TOPOLOGY_HISTORY_END]);
    result = jmx_topology_history_timestamps(start_ms, end_ms);
