static int dw_handle_identity_signal(struct ubus_context *ctx, struct ubus_object *obj,
                                     struct ubus_request_data *req, const char *method,
                                     struct blob_attr *msg)
{
    char *msg_json = NULL;
    struct json_object *in = NULL;
    struct json_object *data;
    struct json_object *resp;
    const char *mac;
    const char *source;
    const char *key;
    const char *value;
    const char *raw;
    int confidence;
    int rc;

    (void)obj;
    (void)method;
    if (msg)
        msg_json = blobmsg_format_json(msg, true);
    if (msg_json)
        in = json_tokener_parse(msg_json);
    if (!in)
        in = json_object_new_object();

    mac = dw_json_get_string(in, "mac", "");
    source = dw_json_get_string(in, "source", "");
    key = dw_json_get_string(in, "key", "");
    value = dw_json_get_string(in, "value", "");
    raw = dw_json_get_string(in, "raw", dw_json_get_string(in, "raw_json", ""));
    confidence = dw_json_get_int(in, "confidence", 50);
    rc = jmx_db_observe_signal(mac, source, key, value, confidence, raw);

    data = json_object_new_object();
    json_object_object_add(data, "ok", json_object_new_boolean(rc == 0));
    if (rc != 0)
        json_object_object_add(data, "error", json_object_new_string("identity_signal_failed"));
    resp = jmx_gen_api_response_data(rc == 0 ? API_CODE_SUCCESS : API_CODE_ERROR, data);
    dw_send_json(ctx, req, resp);
    json_object_put(resp);
    json_object_put(in);
    free(msg_json);
    return 0;
}

