    int p = 1;

    sqlite3_bind_text(st, p++, dw_json_get_string(f, "id", ""), -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, p++, bucket_ts);
    sqlite3_bind_int64(st, p++, bucket_ts);
    sqlite3_bind_int64(st, p++, bucket_ts);
    sqlite3_bind_text(st, p++, dw_json_get_string(f, "proto", ""), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, p++, dw_json_get_string(f, "protocol", dw_json_get_string(f, "proto", "")), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, p++, dw_json_get_string(f, "state", ""), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, p++, dw_json_get_string(f, "app_proto", ""), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, p++, dw_json_get_string(f, "service", ""), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, p++, dw_json_get_string(f, "src", ""), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, p++, dw_json_get_string(f, "dst", ""), -1, SQLITE_TRANSIENT);
    sqlite3_bind_int(st, p++, dw_json_get_int(f, "sport", 0));
