    sqlite3_bind_text(st, p++, dw_json_get_string(f, "source_ip", ""), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, p++, dw_json_get_string(f, "destination_ip", ""), -1, SQLITE_TRANSIENT);
    sqlite3_bind_int(st, p++, dw_json_get_int(f, "source_port", 0));
    sqlite3_bind_int(st, p++, dw_json_get_int(f, "destination_port", 0));
    sqlite3_bind_text(st, p++, dw_json_get_string(f, "direction", ""), -1, SQLITE_TRANSIENT);
