static int dw_storage_level_rank(const char *level)
{
    if (!level || !level[0] || !strcmp(level, "ok"))
        return 0;
    if (!strcmp(level, "warning"))
        return 1;
    return 2;
}

static const char *dw_storage_worse_level(const char *a, const char *b)
{
    return dw_storage_level_rank(a) >= dw_storage_level_rank(b) ? a : b;
}

static void dw_storage_add_reason(struct json_object *reasons,
                                  const char *level,
                                  const char *scope,
                                  const char *name,
                                  const char *reason,
                                  int64_t value,
                                  int64_t threshold)
{
    struct json_object *o;

    if (!reasons || !reason || !reason[0])
        return;
    o = json_object_new_object();
    json_object_object_add(o, "level", json_object_new_string(level && level[0] ? level : "warning"));
    json_object_object_add(o, "scope", json_object_new_string(scope && scope[0] ? scope : "storage"));
    json_object_object_add(o, "name", json_object_new_string(name && name[0] ? name : ""));
    json_object_object_add(o, "reason", json_object_new_string(reason));
    if (value >= 0)
        json_object_object_add(o, "value", json_object_new_int64(value));
    if (threshold >= 0)
        json_object_object_add(o, "threshold", json_object_new_int64(threshold));
    json_object_array_add(reasons, o);
}

static const struct dw_storage_table_limit *dw_storage_table_limit_for(const char *table)
{
    int i;

    if (!table)
        return NULL;
    for (i = 0; dw_storage_table_limits[i].table; i++) {
        if (!strcmp(dw_storage_table_limits[i].table, table))
            return &dw_storage_table_limits[i];
    }
    return NULL;
}

static int dw_storage_table_name_safe(const char *name)
{
    const unsigned char *p = (const unsigned char *)name;

    if (!name || !name[0])
        return 0;
    for (; *p; p++) {
        if (isalnum(*p) || *p == '_')
            continue;
        return 0;
    }
    return 1;
}

static void dw_storage_add_fs(struct json_object *arr, const char *name, const char *path,
                              const char **overall_level, struct json_object *reasons)
{
    struct statvfs vfs;
    struct json_object *o = json_object_new_object();
    unsigned long long total = 0, avail = 0, used = 0;
    double used_pct = 0.0;
    const char *level = "ok";

    json_object_object_add(o, "name", json_object_new_string(name ? name : ""));
    json_object_object_add(o, "path", json_object_new_string(path ? path : ""));
    if (!path || statvfs(path, &vfs) != 0) {
        json_object_object_add(o, "available", json_object_new_boolean(0));
        json_object_object_add(o, "level", json_object_new_string("warning"));
        json_object_object_add(o, "reason", json_object_new_string("statvfs_failed"));
        dw_storage_add_reason(reasons, "warning", "filesystem", name,
                              "statvfs_failed", -1, -1);
        if (overall_level)
            *overall_level = dw_storage_worse_level(*overall_level, "warning");
        json_object_array_add(arr, o);
        return;
    }

    total = (unsigned long long)vfs.f_blocks * (unsigned long long)vfs.f_frsize;
    avail = (unsigned long long)vfs.f_bavail * (unsigned long long)vfs.f_frsize;
    used = total > avail ? total - avail : 0;
    if (total > 0)
        used_pct = (double)used * 100.0 / (double)total;
    if (used_pct >= 95.0)
        level = "critical";
    else if (used_pct >= 85.0)
        level = "warning";

    json_object_object_add(o, "available", json_object_new_boolean(1));
    json_object_object_add(o, "total_bytes", json_object_new_int64((int64_t)total));
    json_object_object_add(o, "used_bytes", json_object_new_int64((int64_t)used));
    json_object_object_add(o, "free_bytes", json_object_new_int64((int64_t)avail));
    json_object_object_add(o, "used_pct", json_object_new_double(used_pct));
    json_object_object_add(o, "level", json_object_new_string(level));
    if (strcmp(level, "ok")) {
        json_object_object_add(o, "reason", json_object_new_string(
            !strcmp(level, "critical") ? "filesystem_usage_critical" : "filesystem_usage_warning"));
        dw_storage_add_reason(reasons, level, "filesystem", name,
                              !strcmp(level, "critical") ? "filesystem_usage_critical" : "filesystem_usage_warning",
                              (int64_t)used_pct, !strcmp(level, "critical") ? 95 : 85);
    }
    if (overall_level)
        *overall_level = dw_storage_worse_level(*overall_level, level);
    json_object_array_add(arr, o);
}

static void dw_storage_tmp_add_top(struct dw_storage_tmp_scan *scan,
                                   const char *path, int64_t size)
{
    int i;
    int pos;

    if (!scan || !path || size < 0)
        return;
    pos = scan->top_count;
    for (i = 0; i < scan->top_count; i++) {
        if (size > scan->top[i].size) {
            pos = i;
            break;
        }
    }
    if (pos >= DW_STORAGE_TMP_TOP_FILES)
        return;
    if (scan->top_count < DW_STORAGE_TMP_TOP_FILES)
        scan->top_count++;
    for (i = scan->top_count - 1; i > pos; i--)
        scan->top[i] = scan->top[i - 1];
    scan->top[pos].size = size;
    snprintf(scan->top[pos].path, sizeof(scan->top[pos].path), "%s", path);
}

static void dw_storage_tmp_scan_dir(struct dw_storage_tmp_scan *scan,
                                    const char *dir_path, int depth)
{
    DIR *dir;
    struct dirent *entry;

    if (!scan || !dir_path || depth > DW_STORAGE_TMP_SCAN_MAX_DEPTH ||
        scan->truncated)
        return;
    dir = opendir(dir_path);
    if (!dir)
        return;
    while ((entry = readdir(dir)) != NULL) {
        char path[512];
        struct stat st;

        if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, ".."))
            continue;
        if (scan->scanned_entries >= DW_STORAGE_TMP_SCAN_MAX_ENTRIES) {
            scan->truncated = 1;
            break;
        }
        scan->scanned_entries++;
        if (snprintf(path, sizeof(path), "%s/%s", dir_path, entry->d_name) >=
            (int)sizeof(path) || lstat(path, &st) != 0 || st.st_dev != scan->device)
            continue;
        if (S_ISREG(st.st_mode)) {
            scan->regular_files++;
            if (st.st_size > 0 &&
                scan->total_regular_bytes <= INT64_MAX - (int64_t)st.st_size)
                scan->total_regular_bytes += (int64_t)st.st_size;
            dw_storage_tmp_add_top(scan, path, (int64_t)st.st_size);
        } else if (S_ISDIR(st.st_mode) && depth < DW_STORAGE_TMP_SCAN_MAX_DEPTH) {
            dw_storage_tmp_scan_dir(scan, path, depth + 1);
        }
    }
    closedir(dir);
}

static void dw_storage_add_tmp_files(struct json_object *data,
                                     const char **overall_level,
                                     struct json_object *reasons)
{
    struct dw_storage_tmp_scan scan;
    struct stat root;
    struct json_object *summary = json_object_new_object();
    struct json_object *largest = json_object_new_array();
    const char *level = "ok";
    const char *reason = "";
    int64_t threshold = -1;
    int i;

    memset(&scan, 0, sizeof(scan));
    if (lstat("/tmp", &root) != 0 || !S_ISDIR(root.st_mode)) {
        json_object_object_add(summary, "available", json_object_new_boolean(0));
        json_object_object_add(summary, "reason",
                               json_object_new_string("tmp_scan_unavailable"));
        json_object_object_add(summary, "largest_files", largest);
        json_object_object_add(data, "tmp_files", summary);
        return;
    }
    scan.device = root.st_dev;
    dw_storage_tmp_scan_dir(&scan, "/tmp", 0);
    if (scan.top_count > 0 &&
        scan.top[0].size >= DW_STORAGE_TMP_CRITICAL_BYTES) {
        level = "critical";
        reason = "tmp_file_size_critical";
        threshold = DW_STORAGE_TMP_CRITICAL_BYTES;
    } else if (scan.top_count > 0 &&
               scan.top[0].size >= DW_STORAGE_TMP_WARN_BYTES) {
        level = "warning";
        reason = "tmp_file_size_warning";
        threshold = DW_STORAGE_TMP_WARN_BYTES;
    }
    for (i = 0; i < scan.top_count; i++) {
        struct json_object *file = json_object_new_object();
        json_object_object_add(file, "path",
                               json_object_new_string(scan.top[i].path));
        json_object_object_add(file, "size_bytes",
                               json_object_new_int64(scan.top[i].size));
        json_object_array_add(largest, file);
    }
    json_object_object_add(summary, "available", json_object_new_boolean(1));
    json_object_object_add(summary, "level", json_object_new_string(level));
    json_object_object_add(summary, "scanned_entries",
                           json_object_new_int(scan.scanned_entries));
    json_object_object_add(summary, "regular_files",
                           json_object_new_int(scan.regular_files));
    json_object_object_add(summary, "total_regular_bytes",
                           json_object_new_int64(scan.total_regular_bytes));
    json_object_object_add(summary, "truncated",
                           json_object_new_boolean(scan.truncated));
    json_object_object_add(summary, "max_entries",
                           json_object_new_int(DW_STORAGE_TMP_SCAN_MAX_ENTRIES));
    json_object_object_add(summary, "max_depth",
                           json_object_new_int(DW_STORAGE_TMP_SCAN_MAX_DEPTH));
    json_object_object_add(summary, "warn_file_bytes",
                           json_object_new_int64(DW_STORAGE_TMP_WARN_BYTES));
    json_object_object_add(summary, "critical_file_bytes",
                           json_object_new_int64(DW_STORAGE_TMP_CRITICAL_BYTES));
    json_object_object_add(summary, "largest_files", largest);
    if (reason[0]) {
        json_object_object_add(summary, "reason", json_object_new_string(reason));
        dw_storage_add_reason(reasons, level, "tmp_file",
            scan.top[0].path, reason, scan.top[0].size, threshold);
        if (overall_level)
            *overall_level = dw_storage_worse_level(*overall_level, level);
    }
    json_object_object_add(data, "tmp_files", summary);
}

static int dw_storage_open_sqlite(const char *path, int write, sqlite3 **db,
                                  char *errbuf, size_t errbuf_len)
{
    int flags = write ? SQLITE_OPEN_READWRITE : SQLITE_OPEN_READONLY;
    int rc;

    if (db)
        *db = NULL;
    if (!path || !db) {
        if (errbuf && errbuf_len)
            snprintf(errbuf, errbuf_len, "%s", "invalid_path");
        return -1;
    }
    rc = sqlite3_open_v2(path, db, flags, NULL);
    if (rc != SQLITE_OK) {
        if (errbuf && errbuf_len)
            snprintf(errbuf, errbuf_len, "%s", *db ? sqlite3_errmsg(*db) : "sqlite_open_failed");
        if (*db)
            sqlite3_close(*db);
        *db = NULL;
        return -1;
    }
    sqlite3_busy_timeout(*db, 3000);
    return 0;
}

static void dw_storage_add_page_stats(sqlite3 *db, struct json_object *o)
{
    int ok = 0;
    int64_t page_size, page_count, freelist_count;

    if (!db || !o)
        return;
    page_size = dw_audit_scalar_i64(db, "PRAGMA page_size", &ok);
    if (ok)
        json_object_object_add(o, "page_size", json_object_new_int64(page_size));
    page_count = dw_audit_scalar_i64(db, "PRAGMA page_count", &ok);
    if (ok)
        json_object_object_add(o, "page_count", json_object_new_int64(page_count));
    freelist_count = dw_audit_scalar_i64(db, "PRAGMA freelist_count", &ok);
    if (ok) {
        json_object_object_add(o, "freelist_count", json_object_new_int64(freelist_count));
        if (page_size > 0)
            json_object_object_add(o, "free_pages_bytes", json_object_new_int64(page_size * freelist_count));
    }
}

static int dw_storage_table_exists(sqlite3 *db, const char *table)
{
    sqlite3_stmt *st = NULL;
    int exists = 0;

    if (!db || !table || sqlite3_prepare_v2(db,
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?1 LIMIT 1",
            -1, &st, NULL) != SQLITE_OK)
        return 0;
    sqlite3_bind_text(st, 1, table, -1, SQLITE_TRANSIENT);
    if (sqlite3_step(st) == SQLITE_ROW)
        exists = 1;
    sqlite3_finalize(st);
    return exists;
}

static int64_t dw_storage_table_rows(sqlite3 *db, const char *table, int *ok)
{
    char sql[160];

    if (ok)
        *ok = 0;
    if (!dw_storage_table_name_safe(table) || !dw_storage_table_exists(db, table))
        return -1;
    snprintf(sql, sizeof(sql), "SELECT COUNT(*) FROM %s", table);
    return dw_audit_scalar_i64(db, sql, ok);
}

static void dw_storage_add_table_counts(sqlite3 *db, struct json_object *o,
                                        const char *db_name,
                                        const char * const *tables,
                                        const char **db_level,
                                        const char **overall_level,
                                        struct json_object *reasons)
{
    struct json_object *arr = json_object_new_array();
    int i;

    if (!o)
        return;
    for (i = 0; tables && tables[i]; i++) {
        int ok = 0;
        int64_t rows = dw_storage_table_rows(db, tables[i], &ok);
        struct json_object *t = json_object_new_object();
        const struct dw_storage_table_limit *limit = dw_storage_table_limit_for(tables[i]);

        json_object_object_add(t, "name", json_object_new_string(tables[i]));
        json_object_object_add(t, "present", json_object_new_boolean(ok));
        if (ok) {
            json_object_object_add(t, "rows", json_object_new_int64(rows));
            if (limit) {
                const char *level = "ok";
                const char *reason = "";
                int64_t threshold = 0;

                json_object_object_add(t, "warn_rows", json_object_new_int64(limit->warn_rows));
                json_object_object_add(t, "critical_rows", json_object_new_int64(limit->critical_rows));
                if (limit->critical_rows > 0 && rows > limit->critical_rows) {
                    level = "critical";
                    reason = "table_rows_critical";
                    threshold = limit->critical_rows;
                } else if (limit->warn_rows > 0 && rows > limit->warn_rows) {
                    level = "warning";
                    reason = "table_rows_warning";
                    threshold = limit->warn_rows;
                }
                json_object_object_add(t, "level", json_object_new_string(level));
                if (reason[0]) {
                    char scope[96], name[160];

                    snprintf(scope, sizeof(scope), "database.%s", db_name ? db_name : "");
                    snprintf(name, sizeof(name), "%s.%s", db_name ? db_name : "", tables[i]);
                    json_object_object_add(t, "reason", json_object_new_string(reason));
                    dw_storage_add_reason(reasons, level, scope, name, reason, rows, threshold);
                    if (db_level)
                        *db_level = dw_storage_worse_level(*db_level, level);
                    if (overall_level)
                        *overall_level = dw_storage_worse_level(*overall_level, level);
                }
            }
        }
        json_object_array_add(arr, t);
    }
    json_object_object_add(o, "tables", arr);
}

static void dw_storage_add_db_status(struct json_object *arr,
                                     const struct dw_storage_db_def *def,
                                     int include_tables,
                                     const char **overall_level,
                                     int64_t *total_bytes,
                                     struct json_object *reasons)
{
    char wal_path[320], shm_path[320], err[128] = "";
    struct json_object *o = json_object_new_object();
    sqlite3 *db = NULL;
    int present;
    int64_t db_size, wal_size, shm_size, sum_size;
    int64_t warn_size = 64LL * 1024LL * 1024LL;
    int64_t critical_size = 256LL * 1024LL * 1024LL;
    const char *level = "ok";
    const char *reason = "";

    /* Audit keeps several bounded, indexed wide tables.  Its configured row
     * caps make the generic 256 MiB critical watermark impossible to satisfy
     * even after retention prune and VACUUM. */
    if (def->name && !strcmp(def->name, "audit")) {
        warn_size = 512LL * 1024LL * 1024LL;
        critical_size = 768LL * 1024LL * 1024LL;
    } else if (def->name && !strcmp(def->name, "logd")) {
        warn_size = 128LL * 1024LL * 1024LL;
        critical_size = 256LL * 1024LL * 1024LL;
    } else if (def->name && !strcmp(def->name, "aegis")) {
        warn_size = 128LL * 1024LL * 1024LL;
        critical_size = 512LL * 1024LL * 1024LL;
    }

    snprintf(wal_path, sizeof(wal_path), "%s-wal", def->path);
    snprintf(shm_path, sizeof(shm_path), "%s-shm", def->path);
    db_size = dw_file_size_or_zero(def->path);
    wal_size = dw_file_size_or_zero(wal_path);
    shm_size = dw_file_size_or_zero(shm_path);
    sum_size = db_size + wal_size + shm_size;
    present = db_size > 0;
    if (total_bytes)
        *total_bytes += sum_size;

    if (def->required && !present) {
        level = "critical";
        reason = "required_db_missing";
    } else if (sum_size >= critical_size) {
        level = "critical";
        reason = "db_size_critical";
    } else if (sum_size >= warn_size) {
        level = "warning";
        reason = "db_size_warning";
    } else if (wal_size >= 64LL * 1024LL * 1024LL) {
        level = "warning";
        reason = "wal_size_warning";
    }

    json_object_object_add(o, "name", json_object_new_string(def->name));
    json_object_object_add(o, "role", json_object_new_string(def->role));
    json_object_object_add(o, "path", json_object_new_string(def->path));
    json_object_object_add(o, "required", json_object_new_boolean(def->required));
    json_object_object_add(o, "present", json_object_new_boolean(present));
    json_object_object_add(o, "db_size_bytes", json_object_new_int64(db_size));
    json_object_object_add(o, "wal_size_bytes", json_object_new_int64(wal_size));
    json_object_object_add(o, "shm_size_bytes", json_object_new_int64(shm_size));
    json_object_object_add(o, "total_size_bytes", json_object_new_int64(sum_size));
    json_object_object_add(o, "warn_size_bytes", json_object_new_int64(warn_size));
    json_object_object_add(o, "critical_size_bytes", json_object_new_int64(critical_size));
    json_object_object_add(o, "level", json_object_new_string(level));
    if (reason[0])
        json_object_object_add(o, "reason", json_object_new_string(reason));
    if (reason[0])
        dw_storage_add_reason(reasons, level, "database", def->name, reason,
                              sum_size, !strcmp(reason, "db_size_critical") ? critical_size :
                              (!strcmp(reason, "db_size_warning") ? warn_size :
                               (!strcmp(reason, "wal_size_warning") ? 64LL * 1024LL * 1024LL : -1)));

    if (present && dw_storage_open_sqlite(def->path, 0, &db, err, sizeof(err)) == 0) {
        dw_storage_add_page_stats(db, o);
        if (include_tables)
            dw_storage_add_table_counts(db, o, def->name, def->tables,
                                        &level, overall_level, reasons);
        json_object_object_del(o, "level");
        json_object_object_add(o, "level", json_object_new_string(level));
        if (strcmp(level, "ok") && !json_object_object_get(o, "reason"))
            json_object_object_add(o, "reason", json_object_new_string("table_watermark_exceeded"));
        sqlite3_close(db);
    } else if (present) {
        json_object_object_add(o, "open_error", json_object_new_string(err[0] ? err : "open_failed"));
        if (!strcmp(level, "ok")) {
            level = "warning";
            json_object_object_del(o, "level");
            json_object_object_add(o, "level", json_object_new_string(level));
        }
        dw_storage_add_reason(reasons, level, "database", def->name,
                              "sqlite_open_failed", -1, -1);
    }

    if (overall_level)
        *overall_level = dw_storage_worse_level(*overall_level, level);
    json_object_array_add(arr, o);
}

static struct json_object *dw_storage_status_json(int include_tables)
{
    struct json_object *data = json_object_new_object();
    struct json_object *filesystems = json_object_new_array();
    struct json_object *dbs = json_object_new_array();
    struct json_object *reasons = json_object_new_array();
    const char *level = "ok";
    int64_t total_db_bytes = 0;
    int i;

    dw_storage_add_fs(filesystems, "root", "/", &level, reasons);
    dw_storage_add_fs(filesystems, "tmp", "/tmp", &level, reasons);
    json_object_object_add(data, "filesystems", filesystems);
    dw_storage_add_tmp_files(data, &level, reasons);

    for (i = 0; dw_storage_dbs[i].name; i++)
        dw_storage_add_db_status(dbs, &dw_storage_dbs[i], include_tables,
                                 &level, &total_db_bytes, reasons);

    json_object_object_add(data, "ok", json_object_new_boolean(strcmp(level, "critical") != 0));
    json_object_object_add(data, "level", json_object_new_string(level));
    json_object_object_add(data, "health", json_object_new_string(level));
    json_object_object_add(data, "status", json_object_new_string(level));
    json_object_object_add(data, "degraded", json_object_new_boolean(strcmp(level, "ok") != 0));
    json_object_object_add(data, "reason", json_object_new_string(
        strcmp(level, "ok") ? "storage_watermark_exceeded" : "storage_ok"));
    json_object_object_add(data, "reasons", reasons);
    json_object_object_add(data, "db_total_size_bytes", json_object_new_int64(total_db_bytes));
    json_object_object_add(data, "databases", dbs);
    json_object_object_add(data, "ts", json_object_new_int64((int64_t)dw_now()));
    return data;
}

static struct json_object *dw_storage_api_status(struct json_object *req)
{
    int include_tables = dw_json_get_bool(req, "tables", 1);
    return jmx_gen_api_response_data(API_CODE_SUCCESS, dw_storage_status_json(include_tables));
}

static int dw_storage_exec_changes(sqlite3 *db, const char *sql, int *changed,
                                   char *errbuf, size_t errbuf_len)
{
    return dw_audit_exec_changes(db, sql, changed, errbuf, errbuf_len);
}

static int64_t dw_storage_count_sql(sqlite3 *db, const char *sql, int64_t def)
{
    int ok = 0;
    int64_t v;

    if (!db || !sql)
        return def;
    v = dw_audit_scalar_i64(db, sql, &ok);
    return ok ? v : def;
}

static int64_t dw_storage_count_sqlf(sqlite3 *db, int64_t def,
                                     const char *fmt, ...)
{
    char sql[768];
    va_list ap;
    int n;

    if (!db || !fmt)
        return def;
    va_start(ap, fmt);
    n = vsnprintf(sql, sizeof(sql), fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= sizeof(sql))
        return def;
    return dw_storage_count_sql(db, sql, def);
}

static void dw_storage_checkpoint(sqlite3 *db, struct json_object *o, int truncate)
{
    int log_frames = 0, checkpointed = 0;
    int rc;

    if (!db || !o)
        return;
    rc = sqlite3_wal_checkpoint_v2(db, NULL,
        truncate ? SQLITE_CHECKPOINT_TRUNCATE : SQLITE_CHECKPOINT_PASSIVE,
        &log_frames, &checkpointed);
    json_object_object_add(o, "checkpoint_rc", json_object_new_int(rc));
    json_object_object_add(o, "checkpoint_log_frames", json_object_new_int(log_frames));
    json_object_object_add(o, "checkpointed_frames", json_object_new_int(checkpointed));
}

static int dw_storage_prune_apid(struct json_object *data, int64_t now,
                                 int retention_days, int max_rows,
                                 int checkpoint, int vacuum, int dry_run)
{
    sqlite3 *db = NULL;
    struct json_object *o = json_object_new_object();
    char err[256] = "";
    char sql[512];
    int changed = 0, total_changed = 0;
    int rc = 0;

    json_object_object_add(o, "name", json_object_new_string("apid"));
    json_object_object_add(o, "path", json_object_new_string(DW_STORAGE_APID_DB_PATH));
    json_object_object_add(o, "dry_run", json_object_new_boolean(dry_run));
    json_object_object_add(data, "apid", o);

    if (dw_storage_open_sqlite(DW_STORAGE_APID_DB_PATH, 1, &db, err, sizeof(err)) != 0) {
        json_object_object_add(o, "ok", json_object_new_boolean(0));
        json_object_object_add(o, "error", json_object_new_string(err[0] ? err : "apid_open_failed"));
        return -1;
    }

    dw_storage_add_page_stats(db, o);
    if (!dry_run) {
        if (dw_storage_exec_changes(db, "BEGIN IMMEDIATE", NULL, err, sizeof(err)) != 0) {
            rc = -1;
            goto done;
        }

        snprintf(sql, sizeof(sql),
                 "DELETE FROM web_sessions WHERE expires_at < %lld OR (revoked=1 AND expires_at < %lld)",
                 (long long)now, (long long)(now - 86400));
        if (dw_storage_exec_changes(db, sql, &changed, err, sizeof(err)) != 0) {
            rc = -1;
            sqlite3_exec(db, "ROLLBACK", NULL, NULL, NULL);
            goto done;
        }
        total_changed += changed;
        json_object_object_add(o, "deleted_expired_sessions", json_object_new_int(changed));

        snprintf(sql, sizeof(sql), "DELETE FROM api_audit_log WHERE ts < %lld",
                 (long long)(now - (int64_t)retention_days * 86400));
        if (dw_storage_exec_changes(db, sql, &changed, err, sizeof(err)) != 0) {
            rc = -1;
            sqlite3_exec(db, "ROLLBACK", NULL, NULL, NULL);
            goto done;
        }
        total_changed += changed;
        json_object_object_add(o, "deleted_api_audit_by_age", json_object_new_int(changed));

        snprintf(sql, sizeof(sql),
                 "DELETE FROM api_audit_log WHERE id IN ("
                 "SELECT id FROM api_audit_log ORDER BY ts DESC,id DESC LIMIT -1 OFFSET %d)",
                 max_rows);
        if (dw_storage_exec_changes(db, sql, &changed, err, sizeof(err)) != 0) {
            rc = -1;
            sqlite3_exec(db, "ROLLBACK", NULL, NULL, NULL);
            goto done;
        }
        total_changed += changed;
        json_object_object_add(o, "deleted_api_audit_by_cap", json_object_new_int(changed));

        if (dw_storage_exec_changes(db, "COMMIT", NULL, err, sizeof(err)) != 0)
            rc = -1;
        if (vacuum && dw_storage_exec_changes(db, "VACUUM", NULL, err, sizeof(err)) != 0)
            rc = -1;
        if (checkpoint)
            dw_storage_checkpoint(db, o, 1);
    } else {
        int64_t sessions, audit_rows, by_age, by_cap, total;
        int64_t cutoff = now - (int64_t)retention_days * 86400;

        sessions = dw_storage_count_sqlf(db, -1,
            "SELECT COUNT(*) FROM web_sessions WHERE expires_at < %lld "
            "OR (revoked=1 AND expires_at < %lld)",
            (long long)now, (long long)(now - 86400));
        audit_rows = dw_storage_count_sql(db, "SELECT COUNT(*) FROM api_audit_log", -1);
        by_age = dw_storage_count_sqlf(db, -1,
            "SELECT COUNT(*) FROM api_audit_log WHERE ts < %lld",
            (long long)cutoff);
        by_cap = dw_storage_count_sqlf(db, -1,
            "SELECT COUNT(*) FROM api_audit_log WHERE id IN ("
            "SELECT id FROM api_audit_log ORDER BY ts DESC,id DESC LIMIT -1 OFFSET %d)",
            max_rows);
        total = dw_storage_count_sqlf(db, -1,
            "SELECT COUNT(*) FROM api_audit_log WHERE ts < %lld OR id IN ("
            "SELECT id FROM api_audit_log ORDER BY ts DESC,id DESC LIMIT -1 OFFSET %d)",
            (long long)cutoff, max_rows);
        json_object_object_add(o, "current_api_audit_rows", json_object_new_int64(audit_rows));
        json_object_object_add(o, "would_delete_expired_sessions", json_object_new_int64(sessions));
        json_object_object_add(o, "would_delete_api_audit_by_age", json_object_new_int64(by_age));
        json_object_object_add(o, "would_delete_api_audit_by_cap", json_object_new_int64(by_cap));
        json_object_object_add(o, "would_delete_api_audit_total", json_object_new_int64(total));
        json_object_object_add(o, "would_delete_rows",
                               json_object_new_int64((sessions > 0 ? sessions : 0) +
                                                     (total > 0 ? total : 0)));
    }

done:
    json_object_object_add(o, "api_audit_retention_days", json_object_new_int(retention_days));
    json_object_object_add(o, "api_audit_max_rows", json_object_new_int(max_rows));
    json_object_object_add(o, "changed_rows", json_object_new_int(total_changed));
    json_object_object_add(o, "ok", json_object_new_boolean(rc == 0));
    if (rc != 0)
        json_object_object_add(o, "sqlite_error", json_object_new_string(err[0] ? err : sqlite3_errmsg(db)));
    dw_storage_add_page_stats(db, o);
    sqlite3_close(db);
    return rc;
}

static int dw_storage_prune_logd(struct json_object *data, int64_t now,
                                 int retention_days, int max_rows,
                                 int checkpoint, int vacuum, int dry_run)
{
    sqlite3 *db = NULL;
    struct json_object *o = json_object_new_object();
    char err[256] = "";
    char sql[512];
    int changed = 0, total_changed = 0;
    int rc = 0;

    json_object_object_add(o, "name", json_object_new_string("logd"));
    json_object_object_add(o, "path", json_object_new_string(DW_STORAGE_LOGD_DB_PATH));
    json_object_object_add(o, "dry_run", json_object_new_boolean(dry_run));
    json_object_object_add(data, "logd", o);

    if (dw_storage_open_sqlite(DW_STORAGE_LOGD_DB_PATH, 1, &db, err, sizeof(err)) != 0) {
        json_object_object_add(o, "ok", json_object_new_boolean(0));
        json_object_object_add(o, "error", json_object_new_string(err[0] ? err : "logd_open_failed"));
        return -1;
    }

    dw_storage_add_page_stats(db, o);
    if (!dry_run) {
        if (dw_storage_exec_changes(db, "BEGIN IMMEDIATE", NULL, err, sizeof(err)) != 0) {
            rc = -1;
            goto done;
        }
        snprintf(sql, sizeof(sql), "DELETE FROM log_events WHERE ts < %lld",
                 (long long)(now - (int64_t)retention_days * 86400));
        if (dw_storage_exec_changes(db, sql, &changed, err, sizeof(err)) != 0) {
            rc = -1;
            sqlite3_exec(db, "ROLLBACK", NULL, NULL, NULL);
            goto done;
        }
        total_changed += changed;
        json_object_object_add(o, "deleted_log_events_by_age", json_object_new_int(changed));

        snprintf(sql, sizeof(sql),
                 "DELETE FROM log_events WHERE id IN ("
                 "SELECT id FROM log_events ORDER BY ts DESC,id DESC LIMIT -1 OFFSET %d)",
                 max_rows);
        if (dw_storage_exec_changes(db, sql, &changed, err, sizeof(err)) != 0) {
            rc = -1;
            sqlite3_exec(db, "ROLLBACK", NULL, NULL, NULL);
            goto done;
        }
        total_changed += changed;
        json_object_object_add(o, "deleted_log_events_by_cap", json_object_new_int(changed));

        if (dw_storage_exec_changes(db, "COMMIT", NULL, err, sizeof(err)) != 0)
            rc = -1;
        if (vacuum && dw_storage_exec_changes(db, "VACUUM", NULL, err, sizeof(err)) != 0)
            rc = -1;
        if (checkpoint)
            dw_storage_checkpoint(db, o, 1);
    } else {
        int64_t log_rows, by_age, by_cap, total;
        int64_t cutoff = now - (int64_t)retention_days * 86400;

        log_rows = dw_storage_count_sql(db, "SELECT COUNT(*) FROM log_events", -1);
        by_age = dw_storage_count_sqlf(db, -1,
            "SELECT COUNT(*) FROM log_events WHERE ts < %lld",
            (long long)cutoff);
        by_cap = dw_storage_count_sqlf(db, -1,
            "SELECT COUNT(*) FROM log_events WHERE id IN ("
            "SELECT id FROM log_events ORDER BY ts DESC,id DESC LIMIT -1 OFFSET %d)",
            max_rows);
        total = dw_storage_count_sqlf(db, -1,
            "SELECT COUNT(*) FROM log_events WHERE ts < %lld OR id IN ("
            "SELECT id FROM log_events ORDER BY ts DESC,id DESC LIMIT -1 OFFSET %d)",
            (long long)cutoff, max_rows);
        json_object_object_add(o, "current_log_event_rows", json_object_new_int64(log_rows));
        json_object_object_add(o, "would_delete_log_events_by_age", json_object_new_int64(by_age));
        json_object_object_add(o, "would_delete_log_events_by_cap", json_object_new_int64(by_cap));
        json_object_object_add(o, "would_delete_log_events_total", json_object_new_int64(total));
        json_object_object_add(o, "would_delete_rows", json_object_new_int64(total));
    }

done:
    json_object_object_add(o, "log_retention_days", json_object_new_int(retention_days));
    json_object_object_add(o, "log_max_rows", json_object_new_int(max_rows));
    json_object_object_add(o, "changed_rows", json_object_new_int(total_changed));
    json_object_object_add(o, "ok", json_object_new_boolean(rc == 0));
    if (rc != 0)
        json_object_object_add(o, "sqlite_error", json_object_new_string(err[0] ? err : sqlite3_errmsg(db)));
    dw_storage_add_page_stats(db, o);
    sqlite3_close(db);
    return rc;
}

static int dw_storage_checkpoint_db(struct json_object *data, const char *name,
                                    const char *path, int truncate, int vacuum,
                                    int dry_run)
{
    sqlite3 *db = NULL;
    struct json_object *o = json_object_new_object();
    char err[256] = "";
    int rc = 0;

    json_object_object_add(o, "name", json_object_new_string(name));
    json_object_object_add(o, "path", json_object_new_string(path));
    json_object_object_add(o, "dry_run", json_object_new_boolean(dry_run));
    json_object_object_add(data, name, o);

    if (dw_file_size_or_zero(path) <= 0) {
        json_object_object_add(o, "ok", json_object_new_boolean(1));
        json_object_object_add(o, "skipped", json_object_new_boolean(1));
        json_object_object_add(o, "reason", json_object_new_string("db_missing"));
        return 0;
    }
    if (dw_storage_open_sqlite(path, 1, &db, err, sizeof(err)) != 0) {
        json_object_object_add(o, "ok", json_object_new_boolean(0));
        json_object_object_add(o, "error", json_object_new_string(err[0] ? err : "open_failed"));
        return -1;
    }
    dw_storage_add_page_stats(db, o);
    if (!dry_run) {
        if (vacuum && dw_storage_exec_changes(db, "VACUUM", NULL, err, sizeof(err)) != 0)
            rc = -1;
        dw_storage_checkpoint(db, o, truncate);
    }
    json_object_object_add(o, "ok", json_object_new_boolean(rc == 0));
    if (rc != 0)
        json_object_object_add(o, "sqlite_error", json_object_new_string(err[0] ? err : sqlite3_errmsg(db)));
    sqlite3_close(db);
    return rc;
}

static struct json_object *dw_storage_api_prune(struct json_object *req)
{
    struct json_object *data = json_object_new_object();
    struct json_object *before = NULL;
    struct json_object *after = NULL;
    int64_t now = (int64_t)dw_now();
    int dry_run = dw_json_get_bool(req, "dry_run", 0);
    int checkpoint = dw_json_get_bool(req, "checkpoint", 1);
    int vacuum = dw_json_get_bool(req, "vacuum", dw_json_get_bool(req, "compact", 0));
    int api_retention_days = dw_json_get_int(req, "api_audit_retention_days", 7);
    int api_max_rows = dw_json_get_int(req, "api_audit_max_rows", 100000);
    int log_retention_days = dw_json_get_int(req, "log_retention_days", 30);
    int log_max_rows = dw_json_get_int(req, "log_max_rows", 50000);
    int rc = 0;

    if (api_retention_days < 1) api_retention_days = 7;
    if (api_max_rows < 1000) api_max_rows = 1000;
    if (log_retention_days < 1) log_retention_days = 30;
    if (log_max_rows < 1000) log_max_rows = 1000;

    json_object_object_add(data, "ok", json_object_new_boolean(1));
    json_object_object_add(data, "dry_run", json_object_new_boolean(dry_run));
    json_object_object_add(data, "checkpoint", json_object_new_boolean(checkpoint));
    json_object_object_add(data, "vacuum", json_object_new_boolean(vacuum));
    json_object_object_add(data, "ts", json_object_new_int64(now));
    before = dw_storage_status_json(0);
    json_object_object_add(data, "before", before);

    if (dw_storage_prune_apid(data, now, api_retention_days, api_max_rows,
                              checkpoint, vacuum, dry_run) != 0)
        rc = -1;
    if (dw_storage_prune_logd(data, now, log_retention_days, log_max_rows,
                              checkpoint, vacuum, dry_run) != 0)
        rc = -1;
    if (!dry_run && dw_audit_prune_default() != 0)
        rc = -1;
    if (!dry_run && jmx_db_prune_and_vacuum() != 0)
        rc = -1;

    if (checkpoint) {
        if (dw_storage_checkpoint_db(data, "config_checkpoint", JMX_NETCONFIG_DB_PATH_DEFAULT, 1, vacuum, dry_run) != 0)
            rc = -1;
        if (dw_storage_checkpoint_db(data, "notify_checkpoint", DW_STORAGE_NOTIFY_DB_PATH, 1, vacuum, dry_run) != 0)
            rc = -1;
        if (dw_storage_checkpoint_db(data, "core_checkpoint", JMX_DB_PATH_DEFAULT, 1, vacuum, dry_run) != 0)
            rc = -1;
        if (dw_storage_checkpoint_db(data, "audit_checkpoint", DW_AUDIT_DB_PATH, 1, vacuum, dry_run) != 0)
            rc = -1;
    }

    after = dw_storage_status_json(1);
    json_object_object_add(data, "after", after);
    json_object_object_del(data, "ok");
    json_object_object_add(data, "ok", json_object_new_boolean(rc == 0));
    return jmx_gen_api_response_data(rc == 0 ? API_CODE_SUCCESS : API_CODE_ERROR, data);
}

static int dw_storage_prune_periodic(void)
{
    struct json_object *data = json_object_new_object();
    int64_t now = (int64_t)dw_now();
    int rc = 0;

    if (!data)
        return -1;
    if (dw_storage_prune_apid(data, now, 7, 100000, 1, 0, 0) != 0)
        rc = -1;
    if (dw_storage_prune_logd(data, now, 30, 50000, 1, 0, 0) != 0)
        rc = -1;
    json_object_put(data);
    return rc;
}

struct dw_flow_sql_text_bind {
    char value[DW_JSON_FILTER_VALUE_LEN];
};

struct dw_flow_sql_build {
    char *buf;
    size_t len;
    size_t used;
    struct dw_flow_sql_text_bind *binds;
    int bind_count;
    int bind_max;
    int truncated;
};

static void dw_flow_sql_append(struct dw_flow_sql_build *b, const char *fmt, ...)
{
    va_list ap;
    int n;

    if (!b || !b->buf || b->used >= b->len || b->truncated)
        return;
    va_start(ap, fmt);
    n = vsnprintf(b->buf + b->used, b->len - b->used, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= b->len - b->used) {
        b->truncated = 1;
        b->buf[b->len - 1] = '\0';
        return;
    }
    b->used += (size_t)n;
}

static void dw_flow_sql_add_bind(struct dw_flow_sql_build *b, const char *value)
{
    if (!b || !b->binds || b->bind_count >= b->bind_max) {
        if (b)
            b->truncated = 1;
        return;
    }
    snprintf(b->binds[b->bind_count].value, sizeof(b->binds[b->bind_count].value), "%s",
             value ? value : "");
    b->bind_count++;
}

static void dw_flow_sql_append_in_list(struct dw_flow_sql_build *b,
                                       const struct dw_json_filter_values *vals)
{
    int i;

    if (!b || !vals)
        return;
    for (i = 0; i < vals->count; i++) {
        if (i > 0)
            dw_flow_sql_append(b, ",");
        dw_flow_sql_append(b, "lower(?)");
        dw_flow_sql_add_bind(b, vals->values[i]);
    }
}

static void dw_flow_sql_add_exact_filter(struct dw_flow_sql_build *b,
                                         const char *expr,
                                         const struct dw_json_filter_values *include,
                                         const struct dw_json_filter_values *exclude)
{
    if (!b || !expr)
        return;
    if (include && include->count > 0) {
        dw_flow_sql_append(b, " AND lower(%s) IN (", expr);
        dw_flow_sql_append_in_list(b, include);
        dw_flow_sql_append(b, ") ");
    }
    if (exclude && exclude->count > 0) {
        dw_flow_sql_append(b, " AND lower(%s) NOT IN (", expr);
        dw_flow_sql_append_in_list(b, exclude);
        dw_flow_sql_append(b, ") ");
    }
}

static void dw_flow_sql_add_dual_exact_filter(struct dw_flow_sql_build *b,
                                              const char *expr1,
                                              const char *expr2,
                                              const struct dw_json_filter_values *include,
                                              const struct dw_json_filter_values *exclude)
{
    if (!b || !expr1 || !expr2)
        return;
    if (include && include->count > 0) {
        dw_flow_sql_append(b, " AND (lower(%s) IN (", expr1);
        dw_flow_sql_append_in_list(b, include);
        dw_flow_sql_append(b, ") OR lower(%s) IN (", expr2);
        dw_flow_sql_append_in_list(b, include);
        dw_flow_sql_append(b, ")) ");
    }
    if (exclude && exclude->count > 0) {
        dw_flow_sql_append(b, " AND lower(%s) NOT IN (", expr1);
        dw_flow_sql_append_in_list(b, exclude);
        dw_flow_sql_append(b, ") AND lower(%s) NOT IN (", expr2);
        dw_flow_sql_append_in_list(b, exclude);
        dw_flow_sql_append(b, ") ");
    }
}

static void dw_flow_sql_add_any_exact_filter(struct dw_flow_sql_build *b,
                                             const char *const *exprs,
                                             int expr_count,
                                             const struct dw_json_filter_values *include,
                                             const struct dw_json_filter_values *exclude)
{
    int i;

    if (!b || !exprs || expr_count <= 0)
        return;
    if (include && include->count > 0) {
        dw_flow_sql_append(b, " AND (");
        for (i = 0; i < expr_count; i++) {
            if (!exprs[i])
                continue;
            if (i > 0)
                dw_flow_sql_append(b, " OR ");
            dw_flow_sql_append(b, "lower(%s) IN (", exprs[i]);
            dw_flow_sql_append_in_list(b, include);
            dw_flow_sql_append(b, ")");
        }
        dw_flow_sql_append(b, ") ");
    }
    if (exclude && exclude->count > 0) {
        dw_flow_sql_append(b, " AND ");
        for (i = 0; i < expr_count; i++) {
            if (!exprs[i])
                continue;
            if (i > 0)
                dw_flow_sql_append(b, " AND ");
            dw_flow_sql_append(b, "lower(%s) NOT IN (", exprs[i]);
            dw_flow_sql_append_in_list(b, exclude);
            dw_flow_sql_append(b, ")");
        }
        dw_flow_sql_append(b, " ");
    }
}

static void dw_flow_sql_add_geo_expr_filter(struct dw_flow_sql_build *b,
                                            const char *country_code_expr,
                                            const char *country_name_expr,
                                            const char *region_code_expr,
                                            const char *region_name_expr,
                                            const char *city_name_expr,
                                            const struct dw_json_filter_values *include,
                                            const struct dw_json_filter_values *exclude)
{
    const char *country_code = country_code_expr ? country_code_expr : "''";
    const char *country_name = country_name_expr ? country_name_expr : "''";
    const char *region_code = region_code_expr ? region_code_expr : "''";
    const char *region_name = region_name_expr ? region_name_expr : "''";
    const char *city_name = city_name_expr ? city_name_expr : "''";

    if (!b)
        return;
    if (include && include->count > 0) {
        dw_flow_sql_append(b, " AND (");
        for (int i = 0; i < include->count; i++) {
            const char *v = include->values[i];

            if (i > 0)
                dw_flow_sql_append(b, " OR ");
            dw_flow_sql_append(b,
                "lower(%s)=lower(?) OR lower(%s)=lower(?) "
                "OR lower(%s)=lower(?) OR lower(%s)=lower(?) "
                "OR lower(%s)=lower(?) "
                "OR lower(%s||':'||%s)=lower(?) "
                "OR lower(%s||':'||%s||':'||%s)=lower(?)",
                country_code, country_name, region_code, region_name, city_name,
                country_code, region_code, country_code, region_code, city_name);
            dw_flow_sql_add_bind(b, v);
            dw_flow_sql_add_bind(b, v);
            dw_flow_sql_add_bind(b, v);
            dw_flow_sql_add_bind(b, v);
            dw_flow_sql_add_bind(b, v);
            dw_flow_sql_add_bind(b, v);
            dw_flow_sql_add_bind(b, v);
        }
        dw_flow_sql_append(b, ") ");
    }
    if (exclude && exclude->count > 0) {
        dw_flow_sql_append(b, " AND NOT (");
        for (int i = 0; i < exclude->count; i++) {
            const char *v = exclude->values[i];

            if (i > 0)
                dw_flow_sql_append(b, " OR ");
            dw_flow_sql_append(b,
                "lower(%s)=lower(?) OR lower(%s)=lower(?) "
                "OR lower(%s)=lower(?) OR lower(%s)=lower(?) "
                "OR lower(%s)=lower(?) "
                "OR lower(%s||':'||%s)=lower(?) "
                "OR lower(%s||':'||%s||':'||%s)=lower(?)",
                country_code, country_name, region_code, region_name, city_name,
                country_code, region_code, country_code, region_code, city_name);
            dw_flow_sql_add_bind(b, v);
            dw_flow_sql_add_bind(b, v);
            dw_flow_sql_add_bind(b, v);
            dw_flow_sql_add_bind(b, v);
            dw_flow_sql_add_bind(b, v);
            dw_flow_sql_add_bind(b, v);
            dw_flow_sql_add_bind(b, v);
        }
        dw_flow_sql_append(b, ") ");
    }
}

static void dw_flow_sql_add_dual_text_filter(struct dw_flow_sql_build *b,
                                             const char *expr1,
                                             const char *expr2,
                                             const struct dw_json_filter_values *include,
                                             const struct dw_json_filter_values *exclude)
{
    if (!b || !expr1 || !expr2)
        return;
    if (include && include->count > 0) {
        dw_flow_sql_append(b, " AND (");
        for (int i = 0; i < include->count; i++) {
            char like[DW_JSON_FILTER_VALUE_LEN + 4];

            if (i > 0)
                dw_flow_sql_append(b, " OR ");
            snprintf(like, sizeof(like), "%%%s%%", include->values[i]);
            dw_flow_sql_append(b, "lower(%s) LIKE lower(?) OR lower(%s) LIKE lower(?)",
                               expr1, expr2);
            dw_flow_sql_add_bind(b, like);
            dw_flow_sql_add_bind(b, like);
        }
        dw_flow_sql_append(b, ") ");
    }
    if (exclude && exclude->count > 0) {
        dw_flow_sql_append(b, " AND NOT (");
        for (int i = 0; i < exclude->count; i++) {
            char like[DW_JSON_FILTER_VALUE_LEN + 4];

            if (i > 0)
                dw_flow_sql_append(b, " OR ");
            snprintf(like, sizeof(like), "%%%s%%", exclude->values[i]);
            dw_flow_sql_append(b, "lower(%s) LIKE lower(?) OR lower(%s) LIKE lower(?)",
                               expr1, expr2);
            dw_flow_sql_add_bind(b, like);
            dw_flow_sql_add_bind(b, like);
        }
        dw_flow_sql_append(b, ") ");
    }
}

static void dw_flow_sql_add_search(struct dw_flow_sql_build *b, const char *search_like,
                                   int lifecycle)
{
    int i;
    int bind_count = 9;

    if (!b || !search_like || !search_like[0])
        return;
    dw_flow_sql_append(b,
        " AND (lower(COALESCE(client_name,'')) LIKE lower(?) "
        "OR lower(COALESCE(client_mac,'')) LIKE lower(?) "
        "OR lower(COALESCE(source_ip,'')) LIKE lower(?) "
        "OR lower(COALESCE(destination_ip,'')) LIKE lower(?) "
        "OR lower(COALESCE(remote_ip,'')) LIKE lower(?) "
        "OR lower(COALESCE(destination_host,'')) LIKE lower(?) "
        "OR lower(COALESCE(host,'')) LIKE lower(?) "
        "OR lower(COALESCE(destination_app_name,'')) LIKE lower(?) "
        "OR lower(COALESCE(service,'')) LIKE lower(?)");
    if (lifecycle == 2) {
        dw_flow_sql_append(b,
            " OR lower(COALESCE(policy_id,'')) LIKE lower(?) "
            "OR lower(COALESCE(policy_name,'')) LIKE lower(?) "
            "OR lower(COALESCE(policy_type,'')) LIKE lower(?) "
            "OR lower(COALESCE(policy_action,'')) LIKE lower(?) "
            "OR lower(COALESCE(policy_source,'')) LIKE lower(?) "
            "OR lower(COALESCE(route_wan,'')) LIKE lower(?) "
            "OR CAST(COALESCE(route_rule_prio,0) AS TEXT) LIKE ? "
            "OR CAST(COALESCE(route_wan_id,0) AS TEXT) LIKE ?");
        bind_count += 8;
    }
    dw_flow_sql_append(b, ") ");
    for (i = 0; i < bind_count; i++)
        dw_flow_sql_add_bind(b, search_like);
}

/*
 * UniFi Insights / Flows 的前端筛选器会同时下发端口、应用、出口网络、
 * 出口接口等维度。audit_flow_sample/audit_flow_lifecycle 已经持久化五元组
 * 与 WAN 归因，因此这些维度必须在 jmxd SQLite 层原生过滤和 COUNT，
 * 不能继续由 webd 只抓一小段样本再后处理，否则分页 total 会误导前端。
 *
 * Geo region、policy/risk overlay 仍不在这里处理：这些需要 GeoIP 或
 * dataplane policy hit producer。source_network/in_interface 与 egress 归因
 * 已随 flow 样本持久化，可以在这里做原生 include/exclude 与精确 COUNT。
 */
static void dw_audit_flow_build_extra_where_from_req(struct dw_flow_sql_build *b,
                                                     struct json_object *req)
{
    struct dw_json_filter_values source_port, destination_port;
    struct dw_json_filter_values exclude_source_port, exclude_destination_port;
    struct dw_json_filter_values app_id, appid, app_text, application;
    struct dw_json_filter_values exclude_app_id, exclude_appid, exclude_app_text, exclude_application;
    struct dw_json_filter_values ingress, source_network_id, in_network_id, in_interface;
    struct dw_json_filter_values exclude_ingress, exclude_source_network_id, exclude_in_network_id, exclude_in_interface;
    struct dw_json_filter_values egress, wan_id, wan_ifname, out_interface;
    struct dw_json_filter_values destination_network_id, out_network_id;
    struct dw_json_filter_values exclude_egress, exclude_wan_id, exclude_wan_ifname, exclude_out_interface;
    struct dw_json_filter_values exclude_destination_network_id, exclude_out_network_id;
    struct dw_json_filter_values source_region, destination_region;
    struct dw_json_filter_values exclude_source_region, exclude_destination_region;
    const char *ingress_exprs[] = {
        "COALESCE(source_network_id,'')",
        "COALESCE(in_network_id,'')",
        "COALESCE(in_interface,'')"
    };
    const char *egress_exprs[] = {
        "COALESCE(wan_id,'')",
        "COALESCE(wan_ifname,'')",
        "COALESCE(destination_network_id,'')",
        "COALESCE(out_network_id,'')",
        "COALESCE(out_interface,'')"
    };

    if (!b || !req)
        return;

    dw_json_get_filter_values(req, "source_port", &source_port);
    dw_json_get_filter_values(req, "destination_port", &destination_port);
    dw_json_get_exclude_filter_values(req, "source_port", &exclude_source_port);
    dw_json_get_exclude_filter_values(req, "destination_port", &exclude_destination_port);
    dw_flow_sql_add_exact_filter(b, "CAST(COALESCE(source_port,0) AS TEXT)",
                                 &source_port, &exclude_source_port);
    dw_flow_sql_add_exact_filter(b, "CAST(COALESCE(destination_port,0) AS TEXT)",
                                 &destination_port, &exclude_destination_port);

    memset(&app_id, 0, sizeof(app_id));
    memset(&exclude_app_id, 0, sizeof(exclude_app_id));
    dw_json_get_filter_values(req, "app_id", &app_id);
    dw_json_get_filter_values(req, "appid", &appid);
    dw_json_filter_values_merge_missing(&app_id, &appid);
    dw_json_get_exclude_filter_values(req, "app_id", &exclude_app_id);
    dw_json_get_exclude_filter_values(req, "appid", &exclude_appid);
    dw_json_filter_values_merge_missing(&exclude_app_id, &exclude_appid);
    dw_flow_sql_add_exact_filter(b, "CAST(COALESCE(destination_app_id,0) AS TEXT)",
                                 &app_id, &exclude_app_id);

    memset(&app_text, 0, sizeof(app_text));
    memset(&exclude_app_text, 0, sizeof(exclude_app_text));
    dw_json_get_filter_values(req, "app", &app_text);
    dw_json_get_filter_values(req, "application", &application);
    dw_json_filter_values_merge_missing(&app_text, &application);
    dw_json_get_exclude_filter_values(req, "app", &exclude_app_text);
    dw_json_get_exclude_filter_values(req, "application", &exclude_application);
    dw_json_filter_values_merge_missing(&exclude_app_text, &exclude_application);
    dw_flow_sql_add_dual_text_filter(b, "COALESCE(destination_app_name,'')",
                                     "COALESCE(service,'')",
                                     &app_text, &exclude_app_text);

    memset(&ingress, 0, sizeof(ingress));
    memset(&exclude_ingress, 0, sizeof(exclude_ingress));
    dw_json_get_filter_values(req, "source_network_id", &source_network_id);
    dw_json_filter_values_merge_missing(&ingress, &source_network_id);
    dw_json_get_filter_values(req, "in_network_id", &in_network_id);
    dw_json_filter_values_merge_missing(&ingress, &in_network_id);
    dw_json_get_filter_values(req, "in_interface", &in_interface);
    dw_json_filter_values_merge_missing(&ingress, &in_interface);

    dw_json_get_exclude_filter_values(req, "source_network_id", &exclude_source_network_id);
    dw_json_filter_values_merge_missing(&exclude_ingress, &exclude_source_network_id);
    dw_json_get_exclude_filter_values(req, "in_network_id", &exclude_in_network_id);
    dw_json_filter_values_merge_missing(&exclude_ingress, &exclude_in_network_id);
    dw_json_get_exclude_filter_values(req, "in_interface", &exclude_in_interface);
    dw_json_filter_values_merge_missing(&exclude_ingress, &exclude_in_interface);

    dw_flow_sql_add_any_exact_filter(b, ingress_exprs,
                                     (int)(sizeof(ingress_exprs) / sizeof(ingress_exprs[0])),
                                     &ingress, &exclude_ingress);

    memset(&egress, 0, sizeof(egress));
    memset(&exclude_egress, 0, sizeof(exclude_egress));
    dw_json_get_filter_values(req, "wan_id", &wan_id);
    dw_json_filter_values_merge_missing(&egress, &wan_id);
    dw_json_get_filter_values(req, "wan_ifname", &wan_ifname);
    dw_json_filter_values_merge_missing(&egress, &wan_ifname);
    dw_json_get_filter_values(req, "out_interface", &out_interface);
    dw_json_filter_values_merge_missing(&egress, &out_interface);
    dw_json_get_filter_values(req, "destination_network_id", &destination_network_id);
    dw_json_filter_values_merge_missing(&egress, &destination_network_id);
    dw_json_get_filter_values(req, "out_network_id", &out_network_id);
    dw_json_filter_values_merge_missing(&egress, &out_network_id);

    dw_json_get_exclude_filter_values(req, "wan_id", &exclude_wan_id);
    dw_json_filter_values_merge_missing(&exclude_egress, &exclude_wan_id);
    dw_json_get_exclude_filter_values(req, "wan_ifname", &exclude_wan_ifname);
    dw_json_filter_values_merge_missing(&exclude_egress, &exclude_wan_ifname);
    dw_json_get_exclude_filter_values(req, "out_interface", &exclude_out_interface);
    dw_json_filter_values_merge_missing(&exclude_egress, &exclude_out_interface);
    dw_json_get_exclude_filter_values(req, "destination_network_id", &exclude_destination_network_id);
    dw_json_filter_values_merge_missing(&exclude_egress, &exclude_destination_network_id);
    dw_json_get_exclude_filter_values(req, "out_network_id", &exclude_out_network_id);
    dw_json_filter_values_merge_missing(&exclude_egress, &exclude_out_network_id);

    dw_flow_sql_add_any_exact_filter(b, egress_exprs,
                                     (int)(sizeof(egress_exprs) / sizeof(egress_exprs[0])),
                                     &egress, &exclude_egress);

    memset(&source_region, 0, sizeof(source_region));
    memset(&destination_region, 0, sizeof(destination_region));
    memset(&exclude_source_region, 0, sizeof(exclude_source_region));
    memset(&exclude_destination_region, 0, sizeof(exclude_destination_region));
    dw_json_get_filter_values(req, "source_region", &source_region);
    dw_json_get_filter_values(req, "destination_region", &destination_region);
    dw_json_get_exclude_filter_values(req, "source_region", &exclude_source_region);
    dw_json_get_exclude_filter_values(req, "destination_region", &exclude_destination_region);
    dw_flow_sql_add_geo_expr_filter(b,
                                    "COALESCE(source_country_code,'')",
                                    "COALESCE(source_country_name,'')",
                                    "COALESCE(source_region_code,'')",
                                    "COALESCE(source_region_name,'')",
                                    "COALESCE(source_city_name,'')",
                                    &source_region, &exclude_source_region);
    dw_flow_sql_add_geo_expr_filter(b,
                                    "COALESCE(destination_country_code,'')",
                                    "COALESCE(destination_country_name,'')",
                                    "COALESCE(destination_region_code,'')",
                                    "COALESCE(destination_region_name,'')",
                                    "COALESCE(destination_city_name,'')",
                                    &destination_region, &exclude_destination_region);
}

static int dw_flow_sql_bind_text_list(sqlite3_stmt *st, int start,
                                      const struct dw_flow_sql_text_bind *binds,
                                      int bind_count)
{
    int i;

    for (i = 0; i < bind_count; i++)
        sqlite3_bind_text(st, start++, binds[i].value, -1, SQLITE_TRANSIENT);
    return start;
}

static void dw_audit_client_app_bucket_build_where(struct dw_flow_sql_build *b,
                                                    const struct dw_json_filter_values *source_mac,
                                                    const struct dw_json_filter_values *source_ip,
                                                    const struct dw_json_filter_values *protocol,
                                                    const struct dw_json_filter_values *service,
                                                    const struct dw_json_filter_values *direction,
                                                    const struct dw_json_filter_values *risk,
                                                    const struct dw_json_filter_values *action,
                                                    const struct dw_json_filter_values *exclude_source_mac,
                                                    const struct dw_json_filter_values *exclude_source_ip,
                                                    const struct dw_json_filter_values *exclude_protocol,
                                                    const struct dw_json_filter_values *exclude_service,
                                                    const struct dw_json_filter_values *exclude_direction,
                                                    const struct dw_json_filter_values *exclude_risk,
                                                    const struct dw_json_filter_values *exclude_action,
                                                    const char *search_like)
{
    if (!b)
        return;
    dw_flow_sql_append(b,
        " FROM audit_client_app_usage_bucket WHERE bucket_ts>=? AND bucket_ts<=? ");
    dw_flow_sql_add_dual_exact_filter(b, "COALESCE(client_mac,'')", "COALESCE(client_key,'')",
                                      source_mac, exclude_source_mac);
    dw_flow_sql_add_dual_exact_filter(b, "COALESCE(client_ip,'')", "COALESCE(client_key,'')",
                                      source_ip, exclude_source_ip);
    dw_flow_sql_add_exact_filter(b, "COALESCE(protocol,'')", protocol, exclude_protocol);
    dw_flow_sql_add_dual_text_filter(b, "COALESCE(service,'')", "COALESCE(app_key,'')",
                                     service, exclude_service);
    dw_flow_sql_add_exact_filter(b, "COALESCE(direction,'')", direction, exclude_direction);
    dw_flow_sql_add_exact_filter(b, "COALESCE(risk,'')", risk, exclude_risk);
    dw_flow_sql_add_exact_filter(b, "COALESCE(action,'')", action, exclude_action);
    if (search_like && search_like[0]) {
        dw_flow_sql_append(b,
            " AND (lower(COALESCE(client_name,'')) LIKE lower(?) "
            "OR lower(COALESCE(client_mac,'')) LIKE lower(?) "
            "OR lower(COALESCE(client_ip,'')) LIKE lower(?) "
            "OR lower(COALESCE(app_key,'')) LIKE lower(?) "
            "OR lower(COALESCE(service,'')) LIKE lower(?) "
            "OR lower(COALESCE(destination_host,'')) LIKE lower(?) "
            "OR lower(COALESCE(host,'')) LIKE lower(?) "
            "OR lower(COALESCE(remote_ip,'')) LIKE lower(?) "
            "OR lower(COALESCE(destination_ip,'')) LIKE lower(?)) ");
        for (int i = 0; i < 9; i++)
            dw_flow_sql_add_bind(b, search_like);
    }
}

static void dw_audit_flow_build_where(struct dw_flow_sql_build *b, int lifecycle,
                                      const struct dw_json_filter_values *source_mac,
                                      const struct dw_json_filter_values *source_ip,
                                      const struct dw_json_filter_values *destination_ip,
                                      const struct dw_json_filter_values *destination_host,
                                      const struct dw_json_filter_values *remote_ip,
                                      const struct dw_json_filter_values *protocol,
                                      const struct dw_json_filter_values *service,
                                      const struct dw_json_filter_values *direction,
                                      const struct dw_json_filter_values *risk,
                                      const struct dw_json_filter_values *action,
                                      const struct dw_json_filter_values *exclude_source_mac,
                                      const struct dw_json_filter_values *exclude_source_ip,
                                      const struct dw_json_filter_values *exclude_destination_ip,
                                      const struct dw_json_filter_values *exclude_destination_host,
                                      const struct dw_json_filter_values *exclude_remote_ip,
                                      const struct dw_json_filter_values *exclude_protocol,
                                      const struct dw_json_filter_values *exclude_service,
                                      const struct dw_json_filter_values *exclude_direction,
                                      const struct dw_json_filter_values *exclude_risk,
                                      const struct dw_json_filter_values *exclude_action,
                                      const char *search_like)
{
    if (!b)
        return;
    if (lifecycle == 2)
        dw_flow_sql_append(b, " FROM audit_flow_event_lifecycle WHERE destroy_ts>=? AND destroy_ts<=? ");
    else
        dw_flow_sql_append(b, lifecycle ?
            " FROM audit_flow_lifecycle WHERE last_seen>=? AND last_seen<=? " :
            " FROM audit_flow_sample WHERE ts>=? AND ts<=? ");
    dw_flow_sql_add_exact_filter(b, "COALESCE(client_mac,'')", source_mac, exclude_source_mac);
    dw_flow_sql_add_dual_exact_filter(b, "COALESCE(source_ip,'')", "COALESCE(client_ip,'')",
                                      source_ip, exclude_source_ip);
    dw_flow_sql_add_exact_filter(b, "COALESCE(destination_ip,'')", destination_ip, exclude_destination_ip);
    dw_flow_sql_add_dual_text_filter(b, "COALESCE(destination_host,'')", "COALESCE(host,'')",
                                     destination_host, exclude_destination_host);
    dw_flow_sql_add_exact_filter(b, "COALESCE(remote_ip,'')", remote_ip, exclude_remote_ip);
    dw_flow_sql_add_exact_filter(b, "COALESCE(protocol,'')", protocol, exclude_protocol);
    dw_flow_sql_add_exact_filter(b, "COALESCE(service,'')", service, exclude_service);
    dw_flow_sql_add_exact_filter(b, "COALESCE(direction,'')", direction, exclude_direction);
    dw_flow_sql_add_exact_filter(b, "COALESCE(risk,'')", risk, exclude_risk);
    dw_flow_sql_add_exact_filter(b, "COALESCE(action,'')", action, exclude_action);
    dw_flow_sql_add_search(b, search_like, lifecycle);
}

