                json_object_object_add(before, "flow_lifecycle_exact", json_object_new_boolean(sqlite3_column_int(st, 59) != 0));
                json_object_object_add(before, "flow_lifecycle_exact_supported", json_object_new_boolean(1));
                json_object_object_add(before, "conntrack_event_lifecycle_supported", json_object_new_boolean(1));
