                if (sqlite3_column_int(st, 70) != 0) {
                    dw_json_replace_bool(before, "policy_supported", 1);
                    dw_json_replace_bool(before, "policy_action_verified", 1);
                    dw_json_replace_string(before, "action_source", "ctnetlink_conntrack_mark");
                    dw_json_replace_string(before, "action_semantic", "verified_policy_route_hit");
                } else {
                    dw_json_replace_bool(before, "policy_supported", 0);
                    dw_json_replace_bool(before, "policy_action_verified", 0);
                    dw_json_replace_string(before, "policy_reason", "no_policy_route_mark_on_this_flow");
                }
                json_object_object_add(before, "exact_byte_timeline", json_object_new_boolean(0));
                json_object_object_add(before, "lifecycle_semantics", json_object_new_string("completed kernel conntrack DESTROY event; first_seen may come from in-memory NEW/UPDATE cache after collector start"));
                json_object_object_add(before, "collector_started_at", json_object_new_int64(event_collector_started_at));
                json_object_object_add(before, "observed_since", json_object_new_int64(event_collector_observed_since));
