static int dw_handle_audit_clear(struct ubus_context *ctx, struct ubus_object *obj,
                                 struct ubus_request_data *req, const char *method,
                                 struct blob_attr *msg)
{
    char *msg_json = msg ? blobmsg_format_json(msg, true) : NULL;
    struct json_object *in = msg_json ? json_tokener_parse(msg_json) : NULL;
    const char *scope = dw_json_get_string(in, "scope", "all");
    struct json_object *root = json_object_new_object(); int rc;
    (void)obj; (void)method;
    rc = dw_audit_clear_db(scope);
    json_object_object_add(root, "ok", json_object_new_boolean(rc == 0));
    json_object_object_add(root, "scope", json_object_new_string(scope));
    json_object_object_add(root, "ts", json_object_new_int64((int64_t)dw_now()));
    dw_send_json(ctx, req, root); json_object_put(root); if(in)json_object_put(in); if(msg_json)free(msg_json); return 0;
}

