/* cidr helper */
static int dw_netmask_to_cidr(const char *mask)
{
    struct in_addr a;
    if (!mask || !mask[0]) return 24;
    if (inet_pton(AF_INET, mask, &a) != 1) return 24;
    uint32_t m = ntohl(a.s_addr);
    int cidr = 0;
    while (m & 0x80000000) { cidr++; m <<= 1; }
    return cidr;
}

