/* Work mode blobmsg policy (must be defined before handlers) */
enum { DW_WORK_MODE_DATA, __DW_WORK_MODE_MAX };
static const struct blobmsg_policy dw_work_mode_policy[] = {
    [DW_WORK_MODE_DATA] = { .name = "data", .type = BLOBMSG_TYPE_TABLE },
};

/* Work mode handlers */
static int dw_handle_work_mode_get(struct ubus_context *ctx, struct ubus_object *obj,
                                   struct ubus_request_data *req, const char *method,
                                   struct blob_attr *msg)
{
    (void)obj; (void)method; (void)msg;
    struct json_object *out = dw_work_mode_get(NULL);
    dw_send_json(ctx, req, out);
    json_object_put(out);
    return 0;
}

static int dw_handle_work_mode_generic(struct ubus_context *ctx, struct ubus_request_data *req,
                                       struct blob_attr *msg,
                                       struct json_object *(*fn)(struct json_object *))
{
    struct blob_attr *tb[__DW_WORK_MODE_MAX];
    blobmsg_parse(dw_work_mode_policy, __DW_WORK_MODE_MAX, tb, blob_data(msg), blob_len(msg));
    char *data_json = tb[DW_WORK_MODE_DATA] ? blobmsg_format_json(tb[DW_WORK_MODE_DATA], true) : NULL;
    struct json_object *in = data_json ? json_tokener_parse(data_json) : json_object_new_object();
    struct json_object *out = fn(in);
    if (!out) out = jmx_gen_api_response_data(API_CODE_ERROR, NULL);
    dw_send_json(ctx, req, out);
    json_object_put(out);
    json_object_put(in);
    free(data_json);
    return 0;
}

static int dw_handle_work_mode_preview(struct ubus_context *ctx, struct ubus_object *obj,
                                       struct ubus_request_data *req, const char *method,
                                       struct blob_attr *msg)
{
    (void)obj; (void)method;
    return dw_handle_work_mode_generic(ctx, req, msg, dw_work_mode_preview);
}

