#undef GS_HANDLER

static const struct blobmsg_policy dw_empty_policy[1] = { };
static const struct blobmsg_policy dw_str_policy[1] = {
    { .name = "id", .type = BLOBMSG_TYPE_STRING },
};

static void dw_send_ok(struct ubus_context *ctx, struct ubus_request_data *req)
{
    struct json_object *r = json_object_new_object();
    json_object_object_add(r, "code", json_object_new_int(2000));
    json_object_object_add(r, "msg", json_object_new_string("ok"));
    dw_send_json(ctx, req, r);
    json_object_put(r);
}

static void dw_send_error(struct ubus_context *ctx, struct ubus_request_data *req,
                          int code, const char *msg)
{
    struct json_object *r = json_object_new_object();
    json_object_object_add(r, "code", json_object_new_int(code));
    json_object_object_add(r, "msg", json_object_new_string(msg));
    dw_send_json(ctx, req, r);
    json_object_put(r);
}

#define dw_json_handler(name, expr) \
static int name(struct ubus_context *ctx, struct ubus_object *obj, \
        struct ubus_request_data *req, const char *method, struct blob_attr *msg) \
{ (void)obj; (void)method; (void)msg; struct json_object *r = (expr); dw_send_json(ctx, req, r); json_object_put(r); return 0; }

#define dw_set_handler(name, fn) \
static int name(struct ubus_context *ctx, struct ubus_object *obj, \
        struct ubus_request_data *req, const char *method, struct blob_attr *msg) \
{ \
    (void)obj; (void)method; \
    char *msg_json = blobmsg_format_json(msg, true); \
    struct json_object *in = msg_json ? json_tokener_parse(msg_json) : NULL; \
    int rc = fn(in); \
    if (rc != 0) { dw_send_error(ctx, req, 500, #fn " failed"); } \
    else { dw_send_ok(ctx, req); } \
    if (in) json_object_put(in); \
    if (msg_json) free(msg_json); \
    return 0; \
}
