{
    (void)obj; (void)method; (void)msg;
    struct json_object *resp = json_object_new_object();
    struct json_object *snapshot = json_object_new_object();
    struct json_object *wans = jmx_netconfig_wan_list();
    struct json_object *lans = jmx_netconfig_lan_list();
    struct json_object *global = jmx_netconfig_global_get();
    struct json_object *dns = jmx_dns_service_get();
    struct json_object *data = NULL;

    if (wans && json_object_object_get_ex(wans, "data", &data) && data) {
        struct json_object *arr = NULL;
        if (json_object_object_get_ex(data, "wans", &arr) && arr)
            json_object_object_add(snapshot, "wans", json_object_get(arr));
    }
    if (lans && json_object_object_get_ex(lans, "data", &data) && data) {
        struct json_object *arr = NULL;
        if (json_object_object_get_ex(data, "lans", &arr) && arr)
            json_object_object_add(snapshot, "lans", json_object_get(arr));
    }
    if (global && json_object_object_get_ex(global, "data", &data) && data) {
        struct json_object *g = NULL;
        if (json_object_object_get_ex(data, "global", &g) && g)
            json_object_object_add(snapshot, "global", json_object_get(g));
    }
    if (dns && json_object_object_get_ex(dns, "data", &data) && data)
        json_object_object_add(snapshot, "dns", json_object_get(data));

    json_object_object_add(resp, "snapshot", snapshot);
    json_object_object_add(resp, "ts", json_object_new_int64(nc_now_s()));
    json_object_object_add(resp, "ok", json_object_new_boolean(1));
    dw_send_json(ctx, req, resp);
    json_object_put(resp);
    if (wans) json_object_put(wans);
    if (lans) json_object_put(lans);
    if (global) json_object_put(global);
    if (dns) json_object_put(dns);
    return 0;
}

static int dw_handle_lan_config_validate(struct ubus_context *ctx, struct ubus_object *obj,
                                         struct ubus_request_data *req, const char *method,
                                         struct blob_attr *msg)
{
    (void)obj; (void)method;
    char *msg_json = msg ? blobmsg_format_json(msg, true) : NULL;
    struct json_object *in = msg_json ? json_tokener_parse(msg_json) : json_object_new_object();
    struct json_object *payload = in;
    struct json_object *wrapped = NULL;
    if (in && json_object_object_get_ex(in, "data", &wrapped) && wrapped)
        payload = wrapped;
    struct json_object *errors = jmx_netconfig_lan_validate(payload);
    struct json_object *data = json_object_new_object();

    json_object_object_add(data, "ok", json_object_new_boolean(errors == NULL));
    json_object_object_add(data, "valid", json_object_new_boolean(errors == NULL));
    json_object_object_add(data, "errors", errors ? errors : json_object_new_array());
    struct json_object *resp = jmx_gen_api_response_data(errors ? API_CODE_ERROR : API_CODE_SUCCESS, data);
    dw_send_json(ctx, req, resp);
    json_object_put(resp);
    if (in) json_object_put(in);
    if (msg_json) free(msg_json);
    return 0;
}

