/* ── wan_apply: SQLite → UCI for one WAN ── */
static int dw_handle_wan_apply(struct ubus_context *ctx, struct ubus_object *obj,
                                struct ubus_request_data *req, const char *method,
                                struct blob_attr *msg)
{
    (void)obj; (void)method;
    char *msg_json = NULL;
    struct json_object *in = NULL, *payload = NULL;
    if (dw_parse_write_payload(ctx, req, msg, &msg_json, &in, &payload) != 0)
        return 0;
    const char *id = dw_json_get_string(payload, "id", "");
    struct json_object *data = json_object_new_object();
    int rc = jmx_netconfig_apply_wan(id);
    json_object_object_add(data, "ok", json_object_new_boolean(rc == 0));
    json_object_object_add(data, "rc", json_object_new_int(rc));
    if (rc != 0)
        json_object_object_add(data, "error", json_object_new_string("wan_apply_failed"));
    struct json_object *resp = jmx_gen_api_response_data(
        rc == 0 ? API_CODE_SUCCESS : API_CODE_ERROR, data);
    dw_send_json(ctx, req, resp);
    if (rc == 0) {
        struct json_object *evt = json_object_new_object();
        json_object_object_add(evt, "id", json_object_new_string(id));
        json_object_object_add(evt, "applied", json_object_new_boolean(1));
        jmx_events_emit("wan.status", "updated", evt);
        json_object_put(evt);
    }
    json_object_put(resp);
    json_object_put(in);
    free(msg_json);
    return 0;
}

