static int dw_handle_file_service_write(struct ubus_context *ctx, struct ubus_object *obj,
                                        struct ubus_request_data *req, const char *method,
                                        struct blob_attr *msg, const char *resource,
                                        int is_delete)
{
    char *msg_json = NULL;
    struct json_object *in = NULL;
    struct json_object *payload = NULL;
    const char *id;
    struct json_object *response;

    (void)obj; (void)method;
    if (dw_parse_write_payload(ctx, req, msg, &msg_json, &in, &payload) != 0)
        return 0;
    id = dw_json_get_string(payload, "id", "");
    if (!strcmp(resource, "samba"))
        response = is_delete ? jmx_samba_share_delete(id, payload) :
                               jmx_samba_share_upsert(id, payload);
    else
        response = is_delete ? jmx_nfs_export_delete(id, payload) :
                               jmx_nfs_export_upsert(id, payload);
    dw_send_owned_json(ctx, req, response);
    if (in) json_object_put(in);
    free(msg_json);
    return 0;
}

