static void dw_copy_json_field(struct json_object *dst, struct json_object *src, const char *key)
{
    struct json_object *v = NULL;

    if (dst && src && key && json_object_object_get_ex(src, key, &v) && v)
        json_object_object_add(dst, key, json_object_get(v));
}

