static int dw_handle_docker_container_action(struct ubus_context *ctx, struct ubus_object *obj,
        struct ubus_request_data *req, const char *method, struct blob_attr *msg)
{
    (void)obj; (void)method;
    char *msg_json = NULL;
    struct json_object *in = NULL;
    struct json_object *payload = NULL;
    struct json_object *data = json_object_new_object();
    const char *id;
    const char *action;
    int rc = -1;

    if (dw_parse_write_payload(ctx, req, msg, &msg_json, &in, &payload) != 0) {
        json_object_put(data);
        return 0;
    }
    id = dw_json_get_string(payload, "id", "");
    action = dw_json_get_string(payload, "action", "");

    if (!dw_json_get_bool(payload, "confirm", 0)) {
        json_object_object_add(data, "ok", json_object_new_boolean(0));
        json_object_object_add(data, "error", json_object_new_string("confirmation_required"));
        json_object_object_add(data, "confirm_required", json_object_new_boolean(1));
    } else if (!strcmp(action, "create"))
        rc = jmx_docker_container_create(payload, data);
    else if (!strcmp(action, "remove"))
        rc = jmx_docker_container_remove(id, payload, data);
    else if (!strcmp(action, "start"))
        rc = jmx_docker_container_start(id, data);
    else if (!strcmp(action, "stop"))
        rc = jmx_docker_container_stop(id, payload, data);
    else if (!strcmp(action, "restart"))
        rc = jmx_docker_container_restart(id, payload, data);
    else if (!strcmp(action, "pause"))
        rc = jmx_docker_container_pause(id, data);
    else if (!strcmp(action, "unpause"))
        rc = jmx_docker_container_unpause(id, data);
    else if (!strcmp(action, "rename"))
        rc = jmx_docker_container_rename(id, payload, data);
    else if (!strcmp(action, "restart_policy"))
        rc = jmx_docker_container_restart_policy(id, payload, data);
    else {
        json_object_object_add(data, "ok", json_object_new_boolean(0));
        json_object_object_add(data, "error", json_object_new_string("invalid_action"));
    }

    struct json_object *r = jmx_gen_api_response_data(rc == 0 ? API_CODE_SUCCESS : API_CODE_ERROR, data);
    dw_send_json(ctx, req, r);
    json_object_put(r);
    if (in) json_object_put(in);
    if (msg_json) free(msg_json);
    return 0;
}

static int dw_handle_docker_image_action(struct ubus_context *ctx, struct ubus_object *obj,
        struct ubus_request_data *req, const char *method, struct blob_attr *msg)
{
    (void)obj; (void)method;
    char *msg_json = NULL;
    struct json_object *in = NULL;
    struct json_object *payload = NULL;
    const char *id;
    const char *action;
    struct json_object *r = NULL;

    if (dw_parse_write_payload(ctx, req, msg, &msg_json, &in, &payload) != 0)
        return 0;
    id = dw_json_get_string(payload, "id", "");
    action = dw_json_get_string(payload, "action", "");

    if (!dw_json_get_bool(payload, "confirm", 0)) {
        struct json_object *data = json_object_new_object();
        json_object_object_add(data, "ok", json_object_new_boolean(0));
        json_object_object_add(data, "error", json_object_new_string("confirmation_required"));
        json_object_object_add(data, "confirm_required", json_object_new_boolean(1));
        r = jmx_gen_api_response_data(API_CODE_ERROR, data);
    } else if (!strcmp(action, "pull")) {
        struct json_object *data = json_object_new_object();
        int rc = jmx_docker_image_pull(payload, data);
        r = jmx_gen_api_response_data(rc == 0 ? API_CODE_SUCCESS : API_CODE_ERROR, data);
    } else if (!strcmp(action, "prune")) {
        struct json_object *data = json_object_new_object();
        json_object_object_add(data, "ok", json_object_new_boolean(0));
        json_object_object_add(data, "error", json_object_new_string("capability_disabled"));
        json_object_object_add(data, "reason", json_object_new_string("image_prune_preview_pending"));
        r = jmx_gen_api_response_data(API_CODE_ERROR, data);
    } else {
        struct json_object *data = json_object_new_object();
        int rc = -1;

        if (!strcmp(action, "remove"))
            rc = jmx_docker_image_remove(id, payload, data);
        else {
            json_object_object_add(data, "ok", json_object_new_boolean(0));
            json_object_object_add(data, "error", json_object_new_string("invalid_action"));
        }
        r = jmx_gen_api_response_data(rc == 0 ? API_CODE_SUCCESS : API_CODE_ERROR, data);
    }

    dw_send_json(ctx, req, r);
    json_object_put(r);
    if (in) json_object_put(in);
    if (msg_json) free(msg_json);
    return 0;
}

