static int dw_handle_ai_tool_authorize(struct ubus_context *ctx, struct ubus_object *obj,
        struct ubus_request_data *req, const char *method, struct blob_attr *msg)
{
    struct blob_attr *tb[4];
    static const struct blobmsg_policy pol[] = {
        { .name = "auth_id", .type = BLOBMSG_TYPE_INT32 },
        { .name = "approve", .type = BLOBMSG_TYPE_INT32 },
        { .name = "role", .type = BLOBMSG_TYPE_STRING },
        { .name = "actor", .type = BLOBMSG_TYPE_STRING },
    };
    if (blobmsg_parse(pol, 4, tb, blob_data(msg), blob_len(msg))) return UBUS_STATUS_INVALID_ARGUMENT;
    int auth_id = tb[0] ? blobmsg_get_u32(tb[0]) : 0;
    int approve = tb[1] ? blobmsg_get_u32(tb[1]) : 0;
    const char *role = tb[2] ? blobmsg_get_string(tb[2]) : "admin";
    const char *actor = tb[3] ? blobmsg_get_string(tb[3]) : role;
    struct json_object *response = jmx_ai_tool_authorization_resolve(auth_id, approve,
                                                                     actor, role);
    dw_send_json(ctx, req, response);
    json_object_put(response);
    return 0;
}

