static int dw_handle_plugin_action(struct ubus_context *ctx, struct ubus_object *obj,
        struct ubus_request_data *req, const char *method, struct blob_attr *msg)
{
    struct blob_attr *tb[2];
    static const struct blobmsg_policy pol[] = {
        { .name = "id", .type = BLOBMSG_TYPE_STRING },
        { .name = "action", .type = BLOBMSG_TYPE_STRING },
    };
    if (blobmsg_parse(pol, 2, tb, blob_data(msg), blob_len(msg))) return UBUS_STATUS_INVALID_ARGUMENT;
    const char *id = tb[0] ? blobmsg_get_string(tb[0]) : "";
    const char *action = tb[1] ? blobmsg_get_string(tb[1]) : "";
    int rc = jmx_plugin_action(id, action);
    if (rc == -2) {
        struct json_object *data = json_object_new_object();
        struct json_object *resp;
        json_object_object_add(data, "ok", json_object_new_boolean(0));
        json_object_object_add(data, "error", json_object_new_string("capability_disabled"));
        json_object_object_add(data, "capability", json_object_new_string("plugin_actions"));
        json_object_object_add(data, "persisted", json_object_new_boolean(0));
        json_object_object_add(data, "applied", json_object_new_boolean(0));
        json_object_object_add(data, "reason",
                               json_object_new_string("trusted_catalog_job_pipeline_pending"));
        resp = jmx_gen_api_response_data(API_CODE_ERROR, data);
        dw_send_json(ctx, req, resp);
        json_object_put(resp);
        return 0;
    }
    if (rc != 0) { dw_send_error(ctx, req, 400, "invalid plugin action"); return 0; }
    dw_send_ok(ctx, req);
    return 0;
}

