static struct ubus_object_type dw_object_type =
    UBUS_OBJECT_TYPE("dreamingwrt", dw_methods);

static struct ubus_object dw_object = {
    .name = "dreamingwrt",
    .type = &dw_object_type,
    .methods = dw_methods,
    .n_methods = ARRAY_SIZE(dw_methods),
};

static struct ubus_object dw_alias_object = {
    .name = "dreamingos",
    .type = &dw_object_type,
    .methods = dw_methods,
    .n_methods = ARRAY_SIZE(dw_methods),
};

static ubus_handler_t dw_original_handlers[ARRAY_SIZE(dw_methods)];

static int dw_core_dispatch_method(struct ubus_context *ctx, struct ubus_object *obj,
                                   struct ubus_request_data *req, const char *method,
                                   struct blob_attr *msg)
{
    size_t i;
    uint64_t call_id = jmx_core_ubus_dispatch_enter("dreamingwrt", method);
    int rc = UBUS_STATUS_METHOD_NOT_FOUND;

    for (i = 0; i < ARRAY_SIZE(dw_methods); i++) {
        if (dw_methods[i].name && !strcmp(dw_methods[i].name, method) &&
            dw_original_handlers[i]) {
            rc = dw_original_handlers[i](ctx, obj, req, method, msg);
            break;
        }
    }

    jmx_core_ubus_dispatch_leave(call_id, rc);
    return rc;
}

static void dw_install_core_dispatcher(void)
{
    size_t i;

    for (i = 0; i < ARRAY_SIZE(dw_methods); i++) {
        if (!dw_original_handlers[i])
            dw_original_handlers[i] = dw_methods[i].handler;
        dw_methods[i].handler = dw_core_dispatch_method;
    }
}

int dreamingwrt_ubus_register(struct ubus_context *ctx)
{
    int ret;
    if (!ctx)
        return -1;
    dw_install_core_dispatcher();
    /*
     * Start the off-loop read pool here: this runs on the main thread after
     * uloop_init() and before any request can arrive, and these ubus objects
     * are its only users. A failure is not fatal; every handler falls back to
     * running inline, which is the pre-existing behaviour.
     *
     * Two workers, not more: the audit reads are disk and page-cache bound on a
     * single sqlite file, so extra threads add contention rather than
     * throughput. It is enough for the concurrent fetches webd issues.
     */
    dw_async_query_set_thread_cleanup(dw_audit_db_worker_cleanup);
    if (dw_async_query_init(2) != 0)
        LOG_WARN("audit async pool unavailable, queries run inline\n");
    ret = ubus_add_object(ctx, &dw_object);
    if (ret != 0) {
        LOG_ERROR("Failed to publish object 'dreamingwrt': %s\n", ubus_strerror(ret));
        return -1;
    }
    ret = ubus_add_object(ctx, &dw_alias_object);
    if (ret != 0) {
        LOG_ERROR("Failed to publish alias object 'dreamingos': %s\n",
                  ubus_strerror(ret));
        ubus_remove_object(ctx, &dw_object);
        return -1;
    }
    return 0;
}

void dreamingwrt_ubus_unregister(struct ubus_context *ctx)
{
    if (!ctx)
        return;
    /*
     * Stop the pool before removing the objects: dw_async_query_stop() drains
     * jobs that already finished, and those completions still need a live ubus
     * object to reply against.
     */
    dw_async_query_stop();
    if (dw_alias_object.id)
        ubus_remove_object(ctx, &dw_alias_object);
    if (dw_object.id)
        ubus_remove_object(ctx, &dw_object);
}
